127: func needNewCertificate(annotations map[string]string, refresh time.Duration, signer *crypto.CA) string {
128: 	now := time.Now()
129: 	notAfterString := annotations[CertificateNotAfterAnnotation]
130: 	if len(notAfterString) == 0 {
131: 		return "missing notAfter"
132: 	}
133: 	notAfter, err := time.Parse(time.RFC3339, notAfterString)
134: 	if err != nil {
135: 		return fmt.Sprintf("bad expiry: %q", notAfterString)
